package completionspec_test

import (
	"fmt"

	"github.com/spf13/cobra"

	"hop.top/kit/go/console/cli/completionspec"
)

func ExampleRenderUsage() {
	root := &cobra.Command{Use: "tool", Short: "Example tool"}
	deploy := &cobra.Command{Use: "deploy <env>", Short: "Deploy", ValidArgs: []string{"prod", "staging"}}
	root.AddCommand(deploy)

	fmt.Print(completionspec.RenderUsage(completionspec.FromCobra(root)))
	// Output:
	// // Generated by `tool completion usage`. Do not edit.
	// name "tool"
	// bin "tool"
	// about "Example tool"
	// cmd "deploy" help="Deploy" {
	//     arg "<env>" {
	//         choices strict=#false "prod" "staging"
	//     }
	// }
}
